def mkpat(r, w):
    out = []
    hard = 0
    for ch in w:
        t = r.choice(['lit', 'lit', 'lit', 'dot', 'cls', 'alt', 'plus', 'opt'])
        if t == 'lit':
            out.append(ch); hard += 1
        elif t == 'dot':
            out.append('.'); hard += 1
        elif t == 'cls':
            out.append('[ab]'); hard += 1
        elif t == 'alt':
            out.append('(a|b)'); hard += 1
        elif t == 'plus':
            out.append(ch + '+'); hard += 1
        else:
            out.append(ch + '?')
        if r.random() < 0.14:
            out.append(r.choice('ab') + '*')
    return ''.join(out), hard


def generate(seed):
    r = random.Random(seed)
    p = q = 'a'
    for _ in range(200):
        w = ''.join(r.choice('ab') for _ in range(r.randint(5, 8)))
        p, hp = mkpat(r, w)
        q, hq = mkpat(r, w)
        if hp >= 2 and hq >= 2 and p != q and len(p) + len(q) < 90:
            return p + ' ' + q
    return p + ' ' + q

